def diamonds(g):
    cells=[(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v]
    ds=[];seen=set()
    for cell in cells:
        if cell in seen: continue
        stack=[cell];comp=[]
        while stack:
            x=stack.pop()
            if x in seen: continue
            seen.add(x);comp.append(x)
            r,c=x
            for n in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if n in cells and n not in seen: stack.append(n)
        top=min(comp);bot=max(comp)
        # tips: up,down,left,right
        up=min(comp,key=lambda x:(x[0],x[1])) if False else None
        tips={'up':min(comp),'down':max(comp),'left':min(comp,key=lambda x:(x[1],x[0])),'right':max(comp,key=lambda x:(x[1],x[0]))}
        ds.append({'cells':set(comp),'tips':tips})
    return ds

DIRS={'up':(-1,0),'down':(1,0),'left':(0,-1),'right':(0,1)}
OPP={'up':'down','down':'up','left':'right','right':'left'}

def transform(g):
    g=[row[:] for row in g]
    ds=diamonds(g)
    for d in ds:
        for tname,(dr,dc) in DIRS.items():
            tip=d['tips'][tname]
            r,c=tip[0]+dr,tip[1]+dc
            while 0<=r<len(g) and 0<=c<len(g[0]):
                if g[r][c]==2:
                    # find the diamond owning (r,c) and check its opposite tip is at (r,c)
                    for e in ds:
                        if (r,c) in e['cells'] and e['tips'][OPP[tname]]==(r,c):
                            # walk back filling 1s from (r,c) to tip exclusive both
                            rr,cc=r-dr,c-dc
                            while (rr,cc)!=tip:
                                g[rr][cc]=1
                                rr-=dr;cc-=dc
                    break
                r+=dr;c+=dc
    return g

